mapper.select:
SELECT i.reg_info_id, i.status_cd, i.reg_no, i.title, i.field_cd, rg.item_cd AS regulation_cd, st.item_cd AS standard_cd, ct.item_cd AS cert_cd, COALESCE(ct.mandatory_yn, st.mandatory_yn, rg.mandatory_yn) AS mandatory_yn, p.target_cd AS product_cd, i.effective_dt, i.version_no, i.field_cd AS field_key, CONCAT(i.field_cd, '|', i.reg_info_id) AS rec_key, CONCAT(i.field_cd, '|', i.reg_info_id, '|', COALESCE(rg.item_cd, '')) AS rule_key, CONCAT(i.field_cd, '|', i.reg_info_id, '|', COALESCE(rg.item_cd, ''), '|', COALESCE(st.item_cd, '')) AS std_key FROM reg_info i LEFT JOIN reg_info_item rg ON rg.reg_info_id = i.reg_info_id AND rg.item_type_cd = 'REGULATION' LEFT JOIN reg_info_item st ON st.parent_item_id = rg.item_id AND st.item_type_cd = 'STANDARD' LEFT JOIN reg_info_item ct ON ct.parent_item_id = st.item_id AND ct.item_type_cd = 'CERT' LEFT JOIN reg_info_target p ON p.reg_info_id = i.reg_info_id AND p.target_type = 'PRODUCT'
WHERE i.reg_info_id IN #{id}
ORDER BY i.field_cd, i.reg_no, rg.sort_order, st.sort_order, ct.sort_order, p.target_cd

SELECT * FROM reg_info_target
 WHERE reg_info_id = #{regInfoId}
 ORDER BY target_type, level_no, target_cd

