INSERT INTO reg_info_item (
    reg_info_id, parent_item_id, item_type_cd, item_cd, level_no, mandatory_yn, remark, sort_order
) VALUES (
    #{regInfoId}, #{parentItemId}, #{itemTypeCd}, #{itemCd}, #{levelNo}, #{mandatoryYn}, #{remark}, #{sortOrder}
)

mapper.update:
UPDATE reg_info_item
   SET parent_item_id = #{parentItemId},
       item_type_cd   = #{itemTypeCd},
       item_cd        = #{itemCd},
       level_no       = #{levelNo},
       mandatory_yn   = #{mandatoryYn},
       remark         = #{remark},
       sort_order     = #{sortOrder}
 WHERE item_id = #{itemId}
   AND reg_info_id = #{regInfoId}

UPDATE reg_info_hist
   SET snapshot_json = #{snapshotJson}
 WHERE hist_id = (
           SELECT MIN(h.hist_id)
             FROM reg_info_hist h
            WHERE h.reg_info_id = #{regInfoId}
              AND h.version_no = #{versionNo}
       )
   AND snapshot_json IS NULL

